#include <bitset>

vector<int> sieve(int n){
    // char num[n+1];
    bitset <10000001> num;
    vector<int> ret;
    for(int i=0;i<=n;i++){
        num[i]=1;
    }
    num[2]=1;
    for (int i=2; i<=n; i++){
        if (num[i]){
            for (int j=2*i;j<=n;j+=i){
                num[j]=0;
            }
            ret.push_back(i);
        }
    }
    return ret;
}

