int main(){
    stack <char> s;
    char a=getchar();
    char b;
    while (~a){
        if (s.empty()){
            s.push(a);
        }
        else{
            b = s.top();
            if (a == 91 || a == 40 || a == 123){
                s.push(a);
            }
            else if (a == b+1 || a == b+2){
                s.pop();
            }
            else{
                cout << "DO NOT MATCH" << endl;
                return 0;
            }
        }
        a = getchar();
    }
    cout << "DO MATCH" << endl;
